.integrations p { font-size:11px; color:var(--muted-foreground); margin:0 0 25px; }
.integration-logos { display:flex; justify-content:center; gap:65px; align-items:center; }
.integration-logo { display:flex; align-items:center; gap:7px; font-weight:700; font-size:21px; }
.integration-logo svg { width:24px; height:24px; }
.integration-logo.mixpanel { font-weight:500; }
.section { padding:92px 0; }
.section-heading { display:flex; justify-content:space-between; gap:50px; align-items:end; margin-bottom:46px; }
.section-heading h2 { margin:15px 0 0; font-size:39px; line-height:1.25; font-weight:600; }
.section-heading > p { color:var(--muted-foreground); font-size:14px; line-height:1.8; max-width:305px; margin:0 0 3px; }
.workflow { display:grid; grid-template-columns: .85fr 1.15fr; gap:66px; align-items:start; }
.flow-step { display:flex; align-items:start; gap:21px; width:100%; padding:20px 0; border-radius:0; border-bottom:1px solid var(--border); text-align:left; white-space:normal; height:auto; justify-content:start; color:var(--muted-foreground); }
