.flow-step.active { color:var(--foreground); }
.step-number { font-family:monospace; font-size:11px; padding-top:5px; color:var(--muted-foreground); }
.flow-step.active .step-number { color:var(--success); }
.step-text strong { display:block; font-size:17px; font-weight:550; }
.step-text p { font-size:12px; line-height:1.8; margin:9px 0 0; font-weight:400; color:var(--muted-foreground); }
.step-arrow { margin-left:auto; margin-top:4px; opacity:0; }
.active .step-arrow { opacity:1; }
.agent-panel { background:var(--ink); color:var(--ink-text); border-radius:7px; overflow:hidden; min-height:373px; box-shadow:var(--shadow-float); }
.panel-top { display:flex; align-items:center; gap:7px; padding:17px 21px; border-bottom:1px solid var(--panel-border); font-size:11px; }
.panel-top > span:last-child { margin-left:auto; color:var(--ink-muted); font-size:9px; }
