.panel-eyebrow { color:var(--ink-muted); font-family:monospace; font-size:10px; }
.panel-content h3 { font-size:22px; font-weight:500; margin:15px 0 8px; }
.panel-content > p { color:var(--ink-muted); font-size:12px; line-height:1.8; }
.event-row { display:flex; align-items:center; gap:10px; font-size:11px; padding:15px 0; border-bottom:1px solid var(--panel-border); }
.event-row svg { color:var(--primary); width:15px; height:15px; }
.event-row span:last-child { margin-left:auto; color:var(--ink-muted); font-size:10px; }
.panel-result { display:flex; justify-content:space-between; align-items:center; padding-top:23px; font-size:11px; color:var(--ink-muted); }
.panel-result strong { color:var(--primary); font-size:14px; font-weight:500; }
.loop-footnote { display:flex; align-items:center; justify-content:center; gap:9px; margin-top:35px; font-size:11px; color:var(--muted-foreground); }
