  color: var(--ink-muted);
  font-size: 12px;
  line-height: 1.8;
}

.event-row {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  padding: 15px 0;
  border-bottom: 1px solid var(--panel-border);
}

.event-row svg {
  color: var(--primary);
  width: 15px;
  height: 15px;
}

.event-row span:last-child {
  margin-left: auto;
  color: var(--ink-muted);
  font-size: 10px;
}

.panel-result {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 23px;
  font-size: 11px;
  color: var(--ink-muted);
}

.panel-result strong {
  color: var(--primary);
  font-size: 14px;
  font-weight: 500;
}

.loop-footnote {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin-top: 35px;
  font-size: 11px;
  color: var(--muted-foreground);
}

.safety-section {
  background: var(--secondary);
  border-block: 1px solid var(--border);
}

.safety-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 55px;
  margin-top: 40px;
}

.safety-item > svg {
  color: var(--success);
  width: 23px;
  height: 23px;
  margin-bottom: 15px;
}

.safety-item h3 {
  font-size: 17px;
  margin: 0 0 12px;
  font-weight: 600;
}

.safety-item p {
  color: var(--muted-foreground);
  font-size: 13px;
  line-height: 1.9;
  margin: 0;
}

.faq-layout {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 70px;
}

.faq-layout h2 {
  font-size: 36px;
  font-weight: 600;
  line-height: 1.25;
  margin: 16px 0 0;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-trigger {
  width: 100%;
  display: flex;
  justify-content: space-between;
  text-align: left;
  white-space: normal;
  padding: 22px 0;
  height: auto;
  border-radius: 0;
  font-size: 14px;
}

.faq-trigger:hover {
  background: transparent;
}

.faq-answer {
  margin: 0;
  padding: 0 35px 23px 0;
  color: var(--muted-foreground);
  font-size: 13px;
  line-height: 1.9;
}

.final-cta {
  text-align: center;
  padding: 70px 20px;
  background: var(--primary);
  color: var(--primary-foreground);
}

.final-cta h2 {
  font-size: 40px;
  line-height: 1.2;
  font-weight: 600;
  margin: 0 0 17px;
}

.final-cta p {
  font-size: 14px;
  margin-bottom: 27px;
}

.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-block: 30px;
}

.footer .brand {
  font-size: 16px;
}

.footer > p {
  font-size: 11px;
  color: var(--muted-foreground);
}

.dialog-description {
  color: var(--muted-foreground);
  font-size: 13px;
  line-height: 1.8;
}

.demo-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 17px;
  gap: 10px;
}

.demo-controls > span {
  color: var(--muted-foreground);
  font-size: 11px;
}

.mobile-menu {
  display: none;
}

.dark .hero-art {
  opacity: 0.1;
}

@media (min-width: 1600px) {
  .hero-art {
    object-position: center 59%;
  }
}

@media (max-width: 800px) {
  .container-page {
    width: calc(100% - 40px);
  }

  .navbar {
    height: 75px;
  }

  .nav-links {
    gap: 20px;
  }

  .nav-links a {
    display: none;
  }

  h1 {
    font-size: 48px;
  }

  .hero {
    min-height: 650px;
  }

  .hero-content {
    padding-top: 58px;
  }

  .hero-copy {
    max-width: 450px;
    padding: 0 15px;
  }

  .integration-logos {
    gap: 30px;
    flex-wrap: wrap;
  }

  .integration-logo {
    font-size: 18px;
  }

  .section {
    padding: 65px 0;
  }

  .section-heading {
    gap: 25px;
  }

  .section-heading h2 {
    font-size: 32px;
  }

  .workflow {
    gap: 30px;
  }

  .safety-grid {
    gap: 25px;
  }

  .faq-layout {
    gap: 30px;
  }
}

@media (max-width: 600px) {
  .brand {
    font-size: 18px;
  }

  .navbar .nav-links > button {
    font-size: 11px;
    padding-inline: 12px;
  }

  h1 {
    font-size: 41px;
    line-height: 1.18;
  }

  .hero {
    min-height: 625px;
  }

  .hero-content {
    padding-top: 41px;
  }

  .hero .eyebrow {
    font-size: 9px;
  }

  .hero-copy {
    font-size: 14px;
    max-width: 340px;
  }

  .hero-art {
    object-position: center bottom;
  }

  .hero-actions {
    gap: 8px;
  }

  .hero-actions button {
    padding-inline: 16px;
    font-size: 12px;
  }

  .activity-float {
    min-width: 0;
    width: calc(100% - 40px);
    gap: 10px;
    padding: 13px;
    bottom: 24px;
  }

  .activity-float p {
    font-size: 11px;
  }

  .activity-float .lift {
    font-size: 11px;
  }

  .integrations {
    padding: 29px 0;
  }

  .integration-logos {
    gap: 24px;
  }

  .integration-logo {
    font-size: 16px;
  }

  .integration-logo svg {
    width: 19px;
  }

  .section-heading {
    display: block;
    margin-bottom: 23px;
  }

  .section-heading h2 {
    font-size: 31px;
  }

  .section-heading > p {
    margin-top: 20px;
  }

  .workflow {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .flow-step {
    padding: 17px 0;
  }

  .safety-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .safety-item {
    padding-left: 43px;
    position: relative;
  }

  .safety-item > svg {
    position: absolute;
    left: 0;
    top: 0;
  }

  .faq-layout {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .faq-layout h2 {
    font-size: 31px;
  }

  .final-cta h2 {
    font-size: 31px;
  }

  .footer {
    align-items: start;
    gap: 15px;
  }

  .footer > p {
    max-width: 125px;
    text-align: right;
    line-height: 1.7;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  * {
    animation: none !important;
    transition: none !important;
  }
}

