import { createFileRoute } from '@tanstack/react-router';
import { useState } from 'react';
import { ArrowDown, ArrowRight, ArrowUpRight, ChartNoAxesCombined, Check, ChevronRight, Github, GitPullRequest, Globe, Layers, Minus, Play, Plus, RotateCcw, ShieldCheck, Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { AgentPreview, steps } from '@/components/agent-preview';
import loopImage from '@/assets/optimization-loop.jpg';

export const Route = createFileRoute('/')({
  head: () => ({ meta: [
    { title: 'Friction Fixer — Your website, better by itself' },
    { name: 'description', content: 'An AI agent that finds what drives visitors away, fixes your website through GitHub, and keeps only the changes that work.' },
    { property: 'og:title', content: 'Friction Fixer — Your website, better by itself' },
    { property: 'og:description', content: 'Observe. Fix. Verify. Repeat. Turn your visitor analytics into a website that improves itself.' },
    { property: 'og:type', content: 'website' },
    { name: 'twitter:card', content: 'summary_large_image' },
  ] }),
  component: Index,
});

const faqs = [
  { question: 'How is this different from an analytics tool?', answer: 'Analytics tells you what happened. Friction Fixer closes the loop: it finds a likely cause, makes a focused code change, and checks the result in your analytics. Insights become improvements, not another dashboard to monitor.' },
  { question: 'What does the agent need to get started?', answer: 'Your website, access to its analytics, and the matching GitHub repository. Visitor behavior provides the signal; your repository is where the agent proposes the fix.' },
  { question: 'Do I stay in control of my website?', answer: 'Yes. Changes are traceable in GitHub, with a clear hypothesis and a focused pull request. The workflow is designed around reviewable changes, measurable results, and reversibility—not unexplained edits.' },
  { question: 'What if a change makes things worse?', answer: 'A fix is only a win if the results support it. When a change does not improve the goal, the agent rolls it back, uses what it learned, and tries another approach.' },
];

function Brand() {
  return <a className="brand" href="#" aria-label="Friction Fixer home"><span className="brand-mark" aria-hidden="true"><svg viewBox="0 0 40 40" fill="none"><path d="M12 4h23l-5 8H18l-4 7h16l-5 8H10L5 36 12 4Z" fill="currentColor" /></svg></span><span>friction fixer<span className="text-success">.</span></span></a>;
}

function Index() {
  const [step, setStep] = useState(0);
  const [openFaq, setOpenFaq] = useState<number | null>(0);
  const [demoOpen, setDemoOpen] = useState(false);
  const [demoStep, setDemoStep] = useState(0);
  const openDemo = () => { setDemoStep(0); setDemoOpen(true); };
  return <>
    <header className="container-page navbar"><Brand /><nav className="nav-links" aria-label="Main navigation"><a href="#how-it-works">How it works</a><a href="#built-for-you">Why Friction Fixer</a><a href="#faq">FAQs</a><Button variant="ink" onClick={openDemo}>Meet your agent <ArrowUpRight /></Button></nav></header>
    <main>
      <section className="hero">
        <img src={loopImage} width={1600} height={1008} className="hero-art" alt="A continuous lime-green ribbon loop flowing through glass checkpoints" fetchPriority="high" />
        <div className="container-page hero-content">
          <div className="eyebrow"><span className="status-dot" /> LESS FRICTION. MORE FORWARD.</div>
          <h1>Friction Fixer.<br />Your website, <span className="highlight-word">better by itself.</span></h1>
          <p className="hero-copy">The AI agent that finds what’s driving visitors away,<br className="hidden sm:block" /> fixes it, and checks that the fix actually worked.</p>
          <div className="hero-actions"><Button variant="hero" size="lg" onClick={openDemo}>Meet your agent <ArrowUpRight /></Button><Button variant="quiet" size="lg" asChild><a href="#how-it-works"><Play size={13} /> See how it works</a></Button></div>
          <p className="hero-note">Your analytics. Your code. A continuous loop of better.</p>
        </div>
        <div className="activity-float"><div className="activity-icon"><Check size={18} /></div><div><p>Less friction. One fix at a time.</p><small>Pricing page improvement verified</small></div><span className="lift">+18.7% <ArrowUpRight size={13} className="inline" /></span></div>
      </section>
      <section className="integrations" aria-label="Analytics and code ecosystem"><div className="container-page"><p>Built around the tools you already use. Not another dashboard.</p><div className="integration-logos"><span className="integration-logo"><ChartNoAxesCombined />PostHog</span><span className="integration-logo mixpanel"><span aria-hidden="true">Ⅲ</span> mixpanel</span><span className="integration-logo"><Layers />Amplitude</span><span className="integration-logo"><Github />GitHub</span></div></div></section>
      <section id="how-it-works" className="container-page section">
        <div className="section-heading"><div><div className="eyebrow"><span className="text-success">01 —</span> THE FEEDBACK LOOP</div><h2>From “why are they leaving?”<br />to “already fixed.”</h2></div><p>No more guessing, endless dashboards,<br className="hidden sm:block" /> or a backlog of “we should fix that.”<br className="hidden sm:block" /> Just a website that keeps getting better.</p></div>
        <div className="workflow"><div role="tablist" aria-label="Agent workflow">{steps.map((item, i) => <Button key={item.title} variant="ghost" className={`flow-step ${step === i ? 'active' : ''}`} role="tab" aria-selected={step === i} aria-controls="workflow-preview" id={`step-${i}`} onClick={() => setStep(i)}><span className="step-number">0{i + 1}</span><span className="step-text"><strong>{item.title}</strong>{step === i && <p>{item.description}</p>}</span><ArrowRight className="step-arrow" /></Button>)}</div><div id="workflow-preview" role="tabpanel" aria-labelledby={`step-${step}`}><AgentPreview step={step} /></div></div>
        <div className="loop-footnote"><RotateCcw size={13} /> Not a one-time audit. A continuous improvement loop.</div>
      </section>
      <section id="built-for-you" className="safety-section"><div className="container-page section"><div className="section-heading"><div><div className="eyebrow"><span className="text-success">02 —</span> AUTONOMOUS, NOT UNACCOUNTABLE</div><h2>Works on its own.<br />Still on your terms.</h2></div><p>Let the agent do the heavy lifting.<br />Keep the visibility and control.</p></div><div className="safety-grid"><div className="safety-item"><GitPullRequest /><h3>Real fixes. In your code.</h3><p>Focused pull requests in your own repository. Every change has a reason, and every line is yours to review.</p></div><div className="safety-item"><ShieldCheck /><h3>Evidence over intuition.</h3><p>The agent measures against your goals. A prettier page isn’t enough—the visitor experience needs to improve.</p></div><div className="safety-item"><RotateCcw /><h3>Nothing is irreversible.</h3><p>Changes that don’t help get undone. No sunk-cost fixes. Just learning that makes the next attempt better.</p></div></div></div></section>
      <section id="faq" className="container-page section faq-layout"><div><div className="eyebrow"><span className="text-success">03 —</span> A FEW GOOD QUESTIONS</div><h2>Curious? Good.<br />So is the agent.</h2></div><div>{faqs.map((faq, i) => <div className="faq-item" key={faq.question}><Button className="faq-trigger" variant="ghost" onClick={() => setOpenFaq(openFaq === i ? null : i)} aria-expanded={openFaq === i} aria-controls={`faq-${i}`}>{faq.question}{openFaq === i ? <Minus /> : <Plus />}</Button>{openFaq === i && <p className="faq-answer" id={`faq-${i}`}>{faq.answer}</p>}</div>)}</div></section>
      <section className="final-cta"><h2>Your next improvement<br />shouldn’t wait on your to-do list.</h2><p>Give your website an agent that closes the loop.</p><Button variant="ink" size="lg" onClick={openDemo}>Meet Friction Fixer <ArrowUpRight /></Button></section>
    </main>
    <footer className="container-page footer"><Brand /><p>© {new Date().getFullYear()} Friction Fixer. Always improving.</p></footer>
    <Dialog open={demoOpen} onOpenChange={setDemoOpen}><DialogContent className="max-w-xl w-[calc(100%-32px)] rounded-lg"><DialogHeader><DialogTitle className="font-display text-xl">Meet your next website improvement.</DialogTitle><DialogDescription className="dialog-description">Follow the agent from the first signal to a verified fix.</DialogDescription></DialogHeader><AgentPreview step={demoStep} /><div className="demo-controls"><span>0{demoStep + 1} / 04 · {['Observe', 'Fix', 'Verify', 'Learn'][demoStep]}</span><Button variant="hero" onClick={() => setDemoStep((demoStep + 1) % 4)}>{demoStep === 3 ? 'Run it again' : 'Next step'}{demoStep === 3 ? <RotateCcw /> : <ArrowRight />}</Button></div></DialogContent></Dialog>
  </>;
}

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
  Outlet,
  Link,
  createRootRouteWithContext,
  useRouter,
  HeadContent,
  Scripts,
  type ErrorComponentProps,
} from "@tanstack/react-router";
import { useEffect, type ReactNode } from "react";

import appCss from "../styles.css?url";
import { reportLovableError } from "../lib/lovable-error-reporting";

function NotFoundComponent() {
  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <div className="max-w-md text-center">
        <h1 className="text-7xl font-bold text-foreground">404</h1>
        <h2 className="mt-4 text-xl font-semibold text-foreground">Page not found</h2>
        <p className="mt-2 text-sm text-muted-foreground">
          The page you're looking for doesn't exist or has been moved.
        </p>
        <div className="mt-6">
          <Link
            to="/"
            className="inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
          >
            Go home
          </Link>
        </div>
      </div>
    </div>
  );
}

function ErrorComponent({ error, reset }: ErrorComponentProps) {
  console.error(error);
  const router = useRouter();
  useEffect(() => {
    reportLovableError(error, { boundary: "tanstack_root_error_component" });
  }, [error]);

  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <div className="max-w-md text-center">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">
          This page didn't load
        </h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Something went wrong on our end. You can try refreshing or head back home.
        </p>
        <div className="mt-6 flex flex-wrap justify-center gap-2">
          <button
            onClick={() => {
              router.invalidate();
              reset();
            }}
            className="inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
          >
            Try again
          </button>
          <a
            href="/"
            className="inline-flex items-center justify-center rounded-md border border-input bg-background px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent"
          >
            Go home
          </a>
        </div>
      </div>
    </div>
  );
}

export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { title: "Friction Fixer — A website that gets better, by itself" },
      { name: "description", content: "Meet the AI agent that finds visitor friction, improves your website, and measures what works." },
      { property: "og:title", content: "Friction Fixer" },
      { property: "og:description", content: "Turn visitor behavior into better website experiences, automatically." },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary_large_image" },
    ],
    links: [
      {
        rel: "stylesheet",
        href: appCss,
      },
      { rel: "icon", href: "/favicon.svg", type: "image/svg+xml" },
      { rel: "stylesheet", href: "https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700&family=Manrope:wght@400;500;600;650;700;750;800&display=swap" },
    ],
  }),
  shellComponent: RootShell,
  component: RootComponent,
  notFoundComponent: NotFoundComponent,
  errorComponent: ErrorComponent,
});

function RootShell({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  );
}

function RootComponent() {
  const { queryClient } = Route.useRouteContext();

  return (
    <QueryClientProvider client={queryClient}>
      {/* Required: nested routes render here. Removing <Outlet /> breaks all child routes. */}
      <Outlet />
    </QueryClientProvider>
  );
} 

